-- New admin-curated template: "Laws of Reflection: Object and Image Distance in a Plane Mirror"
-- (O'Level Physics Practical Workbook, Item 15). A separate experiment - no existing practical is changed.
--
-- Rendered by VirtualLabScenePlaneMirror.vue (render_component 'plane_mirror_pins'): a top view of the
-- soft board, line ML and the normal RS on the white sheet. The student stands the mirror on ML, sticks
-- P1 on RS at y = 2, 4, 6, 8 and 10 cm, and from an eye position sticks P2 and P3 in line with the image
-- of P1 (no parallax: a dotted line of sight on the sheet); removing the mirror, the line through P3 and
-- P2 is produced to meet RS at I; the normal TN is drawn at T and i and r are measured with the protractor
-- (laws of reflection), then x is measured. Below the lab (VirtualLabPlaneMirrorAnalysis.vue):
-- results table, a graph of x against y plotted by hand (gradient about 1: x = y), the relationship,
-- the conclusion for the driver and an assessment. Practical Brief: VirtualLabPlaneMirrorBrief.vue.
-- Adds two catalogue items (soft board, optical pins). Safe to re-run.

-- Icons are UTF-8 byte literals (see migration 123's note) so they survive any client charset.
INSERT IGNORE INTO `virtual_lab_objects` (`object_type`, `display_name`, `category`, `description`, `default_props`, `supported_actions`, `icon`) VALUES
('soft_board', 'Soft Board & White Sheet', 'physics', 'A soft board with a white sheet of paper held by four drawing pins - for ray tracing with optical pins.', '{}', '["move","inspect"]', _utf8mb4 X'F09F938B'),
('optical_pin', 'Optical Pins', 'physics', 'Long, thin pins stuck upright in the soft board to mark rays of light (no-parallax method).', '{}', '["move","inspect"]', _utf8mb4 X'F09F938C');

INSERT INTO `virtual_lab_experiments`
    (`title`, `subject_id`, `topic`, `category`, `difficulty`, `created_by`, `objective`, `introduction`, `apparatus`, `materials`, `safety_precautions`, `scene_objects`, `conclusion_prompt`, `marks`, `is_template`, `status`, `render_mode`, `render_component`, `template_key`, `template_version`)
SELECT
    'Laws of Reflection: Object and Image Distance in a Plane Mirror', (SELECT id FROM subjects WHERE name = 'PHY' LIMIT 1), 'Light - Reflection at Plane Surfaces', 'physics', 'beginner', NULL,
    'To verify the laws of reflection, and to investigate the relationship between the object distance and the distance of its image from a plane mirror.',
    'A driver had his driving mirror broken. He decided to replace it tentatively with a plane mirror instead. While driving, he realised something different from the mirror he was using at first: when a person is far behind his car, it appears too small and far; when the person is near the car, it is shown as a big and near image. This puzzled him.\nWhen he inquired from a friend, he was told that a plane mirror has a property which makes it hard to be used as a driving mirror: the image size and distance from the mirror are the same as the object distance from the mirror. This confused the driver more, and prompted him to ask another fellow driver, who was completely lost but just told him not to use it any more, that it is risky.\nIn that state, the driver is seeking a clear explanation.',
    '1 plane mirror, 1 white sheet of paper, 1 soft board, 4 optical pins, 4 drawing pins and a complete geometry set.',
    'None (all apparatus is simulated).',
    'Handle the mirror and optical pins carefully - they are sharp and the mirror edges can cut; keep the pins upright.',
    '[{"key":"board1","object_type":"soft_board","position":{"x":0,"y":0,"z":0},"in_tray":true},{"key":"mirror1","object_type":"mirror","position":{"x":0,"y":0,"z":0},"in_tray":true},{"key":"pins1","object_type":"optical_pin","position":{"x":0,"y":0,"z":0},"in_tray":true},{"key":"ruler1","object_type":"ruler","position":{"x":0,"y":0,"z":0},"props":{"label":"Ruler (geometry set)"},"in_tray":true},{"key":"protractor1","object_type":"protractor","position":{"x":0,"y":0,"z":0},"props":{"label":"Protractor (geometry set)"},"in_tray":true}]',
    'State what you found about the angles of incidence and reflection, and the relationship between the object distance and the image distance; then explain what the driver observed.',
    30.00, 1, 'published', '2d', 'plane_mirror_pins', 'physics_plane_mirror_object_image_distance', 1
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `virtual_lab_experiments` WHERE `template_key` = 'physics_plane_mirror_object_image_distance');

SET @pm_id = (SELECT id FROM `virtual_lab_experiments` WHERE `template_key` = 'physics_plane_mirror_object_image_distance' LIMIT 1);

-- Steps are only written while the experiment has none, so re-running never disturbs work in progress.
INSERT INTO `virtual_lab_steps` (`experiment_id`, `step_number`, `instruction`, `target_object_key`, `required_action`, `expected_value`, `tolerance`, `hint`, `feedback_correct`, `feedback_incorrect`, `is_safety_check`)
SELECT * FROM (
SELECT @pm_id AS e, 1 AS n, 'Set up: take the soft board with the white sheet, the plane mirror, the optical pins, the ruler and the protractor from the tray. The sheet already has the line ML and the normal RS drawn on it.' AS ins, NULL AS tgt, 'move' AS act, 'apparatus_ready' AS ev, NULL AS tol, 'Click each item in the apparatus tray.' AS h, 'All the apparatus is on the bench.' AS fc, 'Take the remaining apparatus from the tray.' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 2 AS n, 'Stand the plane mirror upright on the line ML.' AS ins, 'mirror1' AS tgt, 'move' AS act, 'ML' AS ev, NULL AS tol, 'Drag the mirror up onto the line ML.' AS h, 'The mirror stands on ML.' AS fc, 'Stand the mirror exactly on ML.' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 3 AS n, 'Stick the object pin P1 on the normal RS, 2.0 cm in front of the mirror (y = 2.0 cm).' AS ins, 'pins1' AS tgt, 'move' AS act, '2.0' AS ev, 0.05 AS tol, 'Click "Stick P1" then click on RS - use the P1 buttons to set it exactly.' AS h, 'P1 is 2.0 cm in front of the mirror.' AS fc, 'Stick P1 exactly 2.0 cm in front of the mirror.' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 4 AS n, 'Look into the mirror from the eye (A): a dotted line of sight appears, pointing at the image of P1. Stick P2 on the dotted line close to the mirror, then P3 on it near the eye - so P3, P2 and the image of P1 are in one straight line.' AS ins, 'pins1' AS tgt, 'move' AS act, 'pins_aligned' AS ev, NULL AS tol, 'Click "Stick P2" and click on the dotted line, then "Stick P3" and click on it near the eye. No dotted line? Drag the eye.||Pins dropped close to the line snap onto it.' AS h, 'P3, P2 and the image of P1 are in one straight line.' AS fc, 'Stick both pins on the dotted line of sight.' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 5 AS n, 'Remove the mirror and draw the ray: click "Remove mirror & draw the ray". The line through P3 and P2 is drawn and produced behind the mirror to meet RS at I.' AS ins, NULL AS tgt, 'move' AS act, 'ray_traced' AS ev, NULL AS tol, 'Click "Remove mirror & draw the ray" on the right.' AS h, 'Ray drawn - it meets RS behind the mirror at the image I.' AS fc, 'Click "Remove mirror & draw the ray".' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 6 AS n, 'Draw the normal TN at T (at right angles to ML) and, with the protractor, measure the angle of incidence i (between the incident ray OT and TN) and the angle of reflection r (between the reflected ray and TN).' AS ins, 'protractor1' AS tgt, 'measure' AS act, NULL AS ev, NULL AS tol, 'Click "Draw the normal & place the protractor at T". Read where each ray crosses the protractor scale (0 at the normal), type i and r, then click "Record".' AS h, 'Angles i and r recorded - compare them.' AS fc, 'Measure the angles i and r at T.' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 7 AS n, 'Measure the image distance x, from the mirror line ML to I along RS: click "Measure x", then "Record".' AS ins, 'ruler1' AS tgt, 'measure' AS act, NULL AS ev, NULL AS tol, 'Click "Measure x", then Record.' AS h, 'Image distance recorded. The mirror goes back on ML for the next trial.' AS fc, 'Measure the image distance x.' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 8 AS n, 'Stick the object pin P1 on the normal RS, 4.0 cm in front of the mirror (y = 4.0 cm).' AS ins, 'pins1' AS tgt, 'move' AS act, '4.0' AS ev, 0.05 AS tol, 'Click "Stick P1" then click on RS - use the P1 buttons to set it exactly.' AS h, 'P1 is 4.0 cm in front of the mirror.' AS fc, 'Stick P1 exactly 4.0 cm in front of the mirror.' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 9 AS n, 'Look into the mirror from the eye (A): a dotted line of sight appears, pointing at the image of P1. Stick P2 on the dotted line close to the mirror, then P3 on it near the eye - so P3, P2 and the image of P1 are in one straight line.' AS ins, 'pins1' AS tgt, 'move' AS act, 'pins_aligned' AS ev, NULL AS tol, 'Click "Stick P2" and click on the dotted line, then "Stick P3" and click on it near the eye. No dotted line? Drag the eye.||Pins dropped close to the line snap onto it.' AS h, 'P3, P2 and the image of P1 are in one straight line.' AS fc, 'Stick both pins on the dotted line of sight.' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 10 AS n, 'Remove the mirror and draw the ray: click "Remove mirror & draw the ray". The line through P3 and P2 is drawn and produced behind the mirror to meet RS at I.' AS ins, NULL AS tgt, 'move' AS act, 'ray_traced' AS ev, NULL AS tol, 'Click "Remove mirror & draw the ray" on the right.' AS h, 'Ray drawn - it meets RS behind the mirror at the image I.' AS fc, 'Click "Remove mirror & draw the ray".' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 11 AS n, 'Draw the normal TN at T (at right angles to ML) and, with the protractor, measure the angle of incidence i (between the incident ray OT and TN) and the angle of reflection r (between the reflected ray and TN).' AS ins, 'protractor1' AS tgt, 'measure' AS act, NULL AS ev, NULL AS tol, 'Click "Draw the normal & place the protractor at T". Read where each ray crosses the protractor scale (0 at the normal), type i and r, then click "Record".' AS h, 'Angles i and r recorded - compare them.' AS fc, 'Measure the angles i and r at T.' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 12 AS n, 'Measure the image distance x, from the mirror line ML to I along RS: click "Measure x", then "Record".' AS ins, 'ruler1' AS tgt, 'measure' AS act, NULL AS ev, NULL AS tol, 'Click "Measure x", then Record.' AS h, 'Image distance recorded. The mirror goes back on ML for the next trial.' AS fc, 'Measure the image distance x.' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 13 AS n, 'Stick the object pin P1 on the normal RS, 6.0 cm in front of the mirror (y = 6.0 cm).' AS ins, 'pins1' AS tgt, 'move' AS act, '6.0' AS ev, 0.05 AS tol, 'Click "Stick P1" then click on RS - use the P1 buttons to set it exactly.' AS h, 'P1 is 6.0 cm in front of the mirror.' AS fc, 'Stick P1 exactly 6.0 cm in front of the mirror.' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 14 AS n, 'Look into the mirror from the eye (A): a dotted line of sight appears, pointing at the image of P1. Stick P2 on the dotted line close to the mirror, then P3 on it near the eye - so P3, P2 and the image of P1 are in one straight line.' AS ins, 'pins1' AS tgt, 'move' AS act, 'pins_aligned' AS ev, NULL AS tol, 'Click "Stick P2" and click on the dotted line, then "Stick P3" and click on it near the eye. No dotted line? Drag the eye.||Pins dropped close to the line snap onto it.' AS h, 'P3, P2 and the image of P1 are in one straight line.' AS fc, 'Stick both pins on the dotted line of sight.' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 15 AS n, 'Remove the mirror and draw the ray: click "Remove mirror & draw the ray". The line through P3 and P2 is drawn and produced behind the mirror to meet RS at I.' AS ins, NULL AS tgt, 'move' AS act, 'ray_traced' AS ev, NULL AS tol, 'Click "Remove mirror & draw the ray" on the right.' AS h, 'Ray drawn - it meets RS behind the mirror at the image I.' AS fc, 'Click "Remove mirror & draw the ray".' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 16 AS n, 'Draw the normal TN at T (at right angles to ML) and, with the protractor, measure the angle of incidence i (between the incident ray OT and TN) and the angle of reflection r (between the reflected ray and TN).' AS ins, 'protractor1' AS tgt, 'measure' AS act, NULL AS ev, NULL AS tol, 'Click "Draw the normal & place the protractor at T". Read where each ray crosses the protractor scale (0 at the normal), type i and r, then click "Record".' AS h, 'Angles i and r recorded - compare them.' AS fc, 'Measure the angles i and r at T.' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 17 AS n, 'Measure the image distance x, from the mirror line ML to I along RS: click "Measure x", then "Record".' AS ins, 'ruler1' AS tgt, 'measure' AS act, NULL AS ev, NULL AS tol, 'Click "Measure x", then Record.' AS h, 'Image distance recorded. The mirror goes back on ML for the next trial.' AS fc, 'Measure the image distance x.' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 18 AS n, 'Stick the object pin P1 on the normal RS, 8.0 cm in front of the mirror (y = 8.0 cm).' AS ins, 'pins1' AS tgt, 'move' AS act, '8.0' AS ev, 0.05 AS tol, 'Click "Stick P1" then click on RS - use the P1 buttons to set it exactly.' AS h, 'P1 is 8.0 cm in front of the mirror.' AS fc, 'Stick P1 exactly 8.0 cm in front of the mirror.' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 19 AS n, 'Look into the mirror from the eye (A): a dotted line of sight appears, pointing at the image of P1. Stick P2 on the dotted line close to the mirror, then P3 on it near the eye - so P3, P2 and the image of P1 are in one straight line.' AS ins, 'pins1' AS tgt, 'move' AS act, 'pins_aligned' AS ev, NULL AS tol, 'Click "Stick P2" and click on the dotted line, then "Stick P3" and click on it near the eye. No dotted line? Drag the eye.||Pins dropped close to the line snap onto it.' AS h, 'P3, P2 and the image of P1 are in one straight line.' AS fc, 'Stick both pins on the dotted line of sight.' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 20 AS n, 'Remove the mirror and draw the ray: click "Remove mirror & draw the ray". The line through P3 and P2 is drawn and produced behind the mirror to meet RS at I.' AS ins, NULL AS tgt, 'move' AS act, 'ray_traced' AS ev, NULL AS tol, 'Click "Remove mirror & draw the ray" on the right.' AS h, 'Ray drawn - it meets RS behind the mirror at the image I.' AS fc, 'Click "Remove mirror & draw the ray".' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 21 AS n, 'Draw the normal TN at T (at right angles to ML) and, with the protractor, measure the angle of incidence i (between the incident ray OT and TN) and the angle of reflection r (between the reflected ray and TN).' AS ins, 'protractor1' AS tgt, 'measure' AS act, NULL AS ev, NULL AS tol, 'Click "Draw the normal & place the protractor at T". Read where each ray crosses the protractor scale (0 at the normal), type i and r, then click "Record".' AS h, 'Angles i and r recorded - compare them.' AS fc, 'Measure the angles i and r at T.' AS fi, 0 AS sc FROM DUAL
UNION ALL SELECT @pm_id AS e, 22 AS n, 'Measure the image distance x, from the mirror line ML to I along RS: click "Measure x", then "Record".' AS ins, 'ruler1' AS tgt, 'measure' AS act, NULL AS ev, NULL AS tol, 'Click "Measure x", then Record.' AS h, 'Image distance recorded. The mirror goes back on ML for the next trial.' AS fc, 'Measure the image distance x.' AS fi, 0 AS sc FROM DUAL
